import React, { useState, useEffect } from 'react';
import './Popup.css';
// Import your image here. Make sure the path is correct.
import popupImage from '../assets/popup-image.jpg'; 

const Popup = () => {
  const [showPopup, setShowPopup] = useState(false);

  useEffect(() => {
    // Show popup after a 2-second delay
    const timer = setTimeout(() => {
      setShowPopup(true);
    }, 2000);
    
    // Cleanup the timer if the component unmounts
    return () => clearTimeout(timer);
  }, []);

  if (!showPopup) return null;

  return (
    <div className="popup-overlay" onClick={() => setShowPopup(false)}>
      {/* (stopPropagation prevents closing when clicking inside the white box) */}
      <div className="popup-box" onClick={(e) => e.stopPropagation()}>
        <button className="close-button" onClick={() => setShowPopup(false)}>
          &times;
        </button>
        
        {/* THE PHOTO */}
        <img src={popupImage} alt="Notice" className="popup-photo" />
        
        {/* OPTIONAL TEXT */}
        <h2>Important Notice</h2>
        <p>Infinity Laghubitta brings you exclusive financial schemes for 2026. Contact your local branch for more details.</p>
        
        <button className="confirm-button" onClick={() => setShowPopup(false)}>
          Understood
        </button>
      </div>
    </div>
  );
};

export default Popup;
